import { Module } from "@nestjs/common";
import { CatalogController } from "./catalog.controller";
import { CATALOG_REPOSITORY, CatalogRepository } from "./catalog.repository";

export const catalogProviders = [
  CatalogRepository,
  { provide: CATALOG_REPOSITORY, useExisting: CatalogRepository },
];
export const catalogExports = [CATALOG_REPOSITORY];

@Module({
  controllers: [CatalogController],
  providers: catalogProviders,
  exports: catalogExports,
})
export class CatalogModule {}
